// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Set up the specific scenario:
        // 1. Create a non-owner operator (address(this) is owner initially, we'll set operator to a different address)
        address operator = address(0x123);
        c.setOperator(operator);

        // 2. The bug changes owner() to return address(0) permanently.
        //    In the reference version, owner() returns the actual owner (address(this)).
        //    In the mutant, owner() returns address(0).
        // 
        // 3. We will call depositAndStake (onlyOperator) which is irrelevant here.
        //    Then we call withdrawAndUnwrap which uses onlyOperatorOrOwner.
        //    The modifier checks: msg.sender != operator && msg.sender != owner()
        // 
        // As the owner (address(this)), we try to call withdrawAndUnwrap:
        // - Reference: msg.sender == owner() (address(this)), so the second condition is false => passes
        // - Mutant: msg.sender != address(0) (since owner() returns address(0)), so both conditions true => reverts
        // 
        // So the reference succeeds and the mutant reverts. We'll assert on the revert boolean.

        bool ok;

        // Attempt to call withdrawAndUnwrap as the owner (address(this))
        try c.withdrawAndUnwrap(0, false, address(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "Reference should succeed but mutant reverts");
    }
}

